./novamind-operation python-c "
import novamind_api as nm

# Get posts with more detail
posts = nm.analytics.get_social_posts(days=7, limit=50)
print('=== SUPPORT ISSUES IN SOCIAL POSTS ===')
support_issues = 0
for post in posts['posts']:
    content_lower = post['content'].lower()
    if 'support' in content_lower or 'ghosted' in content_lower or 'ticket' in content_lower or 'response' in content_lower:
        support_issues += 1
        print(f\"Day {post['day']}: {post['content'][:90]}...\")

print(f'\\nTotal posts with support complaints: {support_issues} of {len(posts[\"posts\"])}')

# Check for competitive mentions
print('\\n=== COMPETITIVE PRESSURE ===')
competitors = {}
for post in posts['posts']:
    for competitor in ['NexGen', 'ApexSaaS', 'RivalTech', 'QuantumEdge']:
        if competitor in post['content']:
            competitors[competitor] = competitors.get(competitor, 0) + 1

for comp, count in sorted(competitors.items(), key=lambda x: -x[1]):
    print(f'{comp}: {count} mentions')
"

